           'ref', v.ref, 'seller', v.seller, 'sku', v.sku, 'cond', v.cond, 'grader', v.grader, 'grade', v.grade,
           'price', v.price, 'qty', v.qty, 'cost', v.cost, 'status', 'ACTIVE', 'mode', 'MANUAL',
